<?php require_once __DIR__.'/includes/bootstrap.php';require_verified();$u=current_user();$staff=in_array($u['role'],['admin','librarian'],true);$status=$_GET['status']??'';$q=trim($_GET['q']??'');$sql='SELECT br.*,b.title,b.author,u.full_name member_name FROM borrowings br JOIN books b ON b.id=br.book_id JOIN users u ON u.id=br.user_id WHERE 1=1';$types='';$p=[];if(!$staff){$sql.=' AND br.user_id=?';$types.='i';$p[]=(int)$u['id'];}if(in_array($status,['pending','approved','borrowed','returned','rejected'],true)){$sql.=' AND br.status=?';$types.='s';$p[]=$status;}if($q!==''){$sql.=' AND (b.title LIKE ? OR u.full_name LIKE ?)';$like="%$q%";$types.='ss';$p[]=$like;$p[]=$like;}$sql.=' ORDER BY br.id DESC';$s=$conn->prepare($sql);if($types)$s->bind_param($types,...$p);$s->execute();$rows=$s->get_result();page_header('Borrowing');?><div class="page-heading"><div><p class="eyebrow">TRANSACTION WORKFLOW</p><h1>Borrowing records</h1><p class="muted">Request → Approval → Release → Return</p></div><a class="btn secondary" href="reports.php">Printable report</a></div><form class="filter-bar"><input name="q" value="<?=e($q)?>" placeholder="Search book or member"><select name="status"><option value="">All statuses</option><?php foreach(['pending','approved','borrowed','returned','rejected'] as $x):?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=ucfirst($x)?></option><?php endforeach;?></select><button class="btn">Filter</button></form><div class="table-wrap panel"><table><thead><tr><th>ID</th><th>Member</th><th>Book</th><th>Requested</th><th>Due</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if($rows->num_rows):while($r=$rows->fetch_assoc()):?><tr><td>#<?=$r['id']?></td><td><?=e($r['member_name'])?></td><td><?=e($r['title'])?></td><td><?=e($r['requested_at'])?></td><td><?=e($r['due_date']??'—')?></td><td><?=status_badge($r['status'])?></td><td><?php if($staff):?><form method="post" action="actions/borrowing_transition.php" class="inline-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="action" required><option value="">Choose</option><?php if($r['status']==='pending'):?><option value="approve">Approve</option><option value="reject">Reject</option><?php elseif($r['status']==='approved'):?><option value="release">Release</option><?php elseif($r['status']==='borrowed'):?><option value="return">Return</option><?php endif;?></select><button class="btn small-btn">Apply</button></form><?php else:?><span class="muted small">Awaiting staff</span><?php endif;?></td></tr><?php endwhile;else:?><tr><td colspan="7" class="empty">No records found.</td></tr><?php endif;?></tbody></table></div><?php page_footer();?>